<?php elseif ($editor): ?><?php writeForm($categories,$post,$categoryId); ?>
<?php elseif ($post): ?><div class="notice"><a href="/?category=<?=$post['category_id']?>"><?=icon('grid')?> <?=e($post['category_name'])?></a><a href="/">Back to feed →</a></div><article class="panel article"><div class="author-row"><span class="avatar">B</span><div><strong>Brainpress</strong><div class="muted"><?=e(substr($post['created_at'],0,16))?> · Published</div></div><a class="edit-post" href="/?edit=<?=$post['id']?>"><?=icon('edit')?> Edit</a></div><h1><?=e($post['title'])?></h1><div class="prose"><?=markdown($post['markdown'])?></div><footer class="article-end"><a class="category-badge" href="/?category=<?=$post['category_id']?>"><?=icon('grid')?> <?=e($post['category_name'])?> ›</a><button class="text-button" data-share="/?post=<?=$post['id']?>"><?=icon('share')?> Copy link</button></footer></article>
<?php elseif ($categoryView): ?><div class="notice"><?=icon('grid')?> Browse your categories</div><div class="section-heading"><h1>Categories</h1><button class="text-button" data-add-category>＋ Create category</button></div><div class="category-grid"><?php foreach ($categories as $c): ?><a class="panel category-card" href="/?category=<?=$c['id']?>"><span class="category-icon"><?=icon('grid')?></span><div><h2><?=e($c['name'])?></h2><p><?=$c['total']?> <?=$c['total']==1?'post':'posts'?></p></div><?=icon('arrow')?></a><?php endforeach; ?></div><?php if (!$categories): ?><div class="panel empty"><h2>No categories yet</h2><button class="button" data-add-category>Create your first category</button></div><?php endif; ?>
<?php else: ?><div class="notice"><span><?=icon('chat')?> <?=$categoryId ? e($categoryName) : 'Welcome to your personal publishing space.'?></span><span><?=$filteredTotal?> posts</span></div><?php if (!$categoryId && empty($_GET['q']) && $page===1): ?><?php writeForm($categories,null,0,true); ?><?php endif; ?><div class="post-list"><?php foreach ($posts as $p): ?><article class="panel post-card"><div class="author-row"><span class="avatar">B</span><div><strong>Brainpress</strong><div class="muted"><?=e(substr($p['created_at'],0,16))?> · Published</div></div><a class="post-open" href="/?post=<?=$p['id']?>">Read <?=icon('arrow')?></a></div><div class="post-body"><h2><a href="/?post=<?=$p['id']?>"><?=e($p['title'])?></a></h2><p><?=e(excerpt($p['markdown']))?></p><?php if (preg_match('~!\[[^\]]*\]\((/uploads/[a-f0-9]+\.(?:png|jpg|gif|webp))(?:[\s\)])[\s\S]*~',$p['markdown'],$img)): ?><a class="card-image" href="/?post=<?=$p['id']?>"><img src="<?=e($img[1])?>" alt="Post image" loading="lazy"></a><?php endif; ?><footer><a class="category-badge" href="/?category=<?=$p['category_id']?>"><?=icon('grid')?> <?=e($p['category_name'])?> ›</a><button class="text-button" data-share="/?post=<?=$p['id']?>"><?=icon('share')?> Share</button></footer></div></article><?php endforeach; ?><?php if (!$posts): ?><div class="panel empty"><h2><?=empty($_GET['q']) ? 'Your feed starts here' : 'No matching posts'?></h2><p><?=empty($_GET['q']) ? 'Publish a thought, a note, or something worth keeping.' : 'Try another search.'?></p></div><?php endif; ?></div><?php if ($filteredTotal > $limit): ?><nav class="pagination"><?php if ($page>1): ?><a href="/?category=<?=$categoryId?>&q=<?=urlencode($_GET['q']??'')?>&page=<?=$page-1?>">← Previous</a><?php endif; ?><span><?=$page?> / <?=(int)ceil($filteredTotal/$limit)?></span><?php if ($page*$limit<$filteredTotal): ?><a href="/?category=<?=$categoryId?>&q=<?=urlencode($_GET['q']??'')?>&page=<?=$page+1?>">Next →</a><?php endif; ?></nav><?php endif; ?><?php 